export class ReverseGeocoder {
  constructor(mapsetReader, wordbookReader, options = {}) {
    if (mapsetReader === null || mapsetReader === undefined) {
      throw new TypeError("mapsetReader is required");
    }
    if (wordbookReader === null || wordbookReader === undefined) {
      throw new TypeError("wordbookReader is required");
    }
    this.mapsetReader = mapsetReader;
    this.wordbookReader = wordbookReader;
    this.separator = options.separator ?? " / ";
    this.omitEmpty = options.omitEmpty ?? true;
  }

  reverseGeocode(lon, lat, options = {}) {
    validateLonLat(lon, lat);
    const point = this.wgsToPoint(lon, lat);
    const code = this.mapsetReader.readWgsPoint(point.x, point.y);
    const path = this.wordbookReader.readStringSetByCode(code);
    const name = formatAddressPath(path, {
      separator: options.separator ?? this.separator,
      omitEmpty: options.omitEmpty ?? this.omitEmpty,
    });

    return {
      lon,
      lat,
      point,
      code,
      path,
      name,
      found: path !== null,
    };
  }

  readCode(lon, lat) {
    validateLonLat(lon, lat);
    const point = this.wgsToPoint(lon, lat);
    return this.mapsetReader.readWgsPoint(point.x, point.y);
  }

  readPath(lon, lat) {
    const code = this.readCode(lon, lat);
    return this.wordbookReader.readStringSetByCode(code);
  }

  wgsToPoint(lon, lat) {
    validateLonLat(lon, lat);
    return {
      x: Math.round(lon * this.mapsetReader.unitInvX),
      y: Math.round(lat * this.mapsetReader.unitInvY),
    };
  }
}

export function formatAddressPath(path, options = {}) {
  if (path === null || path === undefined) {
    return null;
  }
  const separator = options.separator ?? " / ";
  const omitEmpty = options.omitEmpty ?? true;
  const components = omitEmpty ? path.filter((component) => component !== "") : path;
  const name = components.join(separator);
  return name.length > 0 ? name : null;
}

function validateLonLat(lon, lat) {
  if (!Number.isFinite(lon) || !Number.isFinite(lat)) {
    throw new TypeError("lon and lat must be finite numbers");
  }
}
