export class Color {
  constructor(r, g, b, a = 255) {
    this.r = r;
    this.g = g;
    this.b = b;
    this.a = a;
  }
}

export class MapFillRenderOptions {
  constructor({
    defaultColor = new Color(0, 0, 0, 0),
    colors = new Map(),
    colorResolver = null,
  } = {}) {
    this.defaultColor = defaultColor;
    this.colors = colors;
    this.colorResolver = colorResolver;
  }
}

export class MapEdgeRenderOptions {
  constructor({
    edgeColor = new Color(0, 0, 0, 255),
    backgroundColor = new Color(0, 0, 0, 0),
    edgeWidth = 1,
    includeZero = false,
  } = {}) {
    this.edgeColor = edgeColor;
    this.backgroundColor = backgroundColor;
    this.edgeWidth = edgeWidth;
    this.includeZero = includeZero;
  }
}

export class MapImageRenderOptions {
  constructor({
    fillOptions = new MapFillRenderOptions(),
    edgeOptions = new MapEdgeRenderOptions(),
  } = {}) {
    this.fillOptions = fillOptions;
    this.edgeOptions = edgeOptions;
  }
}
