import { ReverseGeocoder, formatAddressPath } from "../../api/geocode/ReverseGeocoder.js";
import {
  Color,
  MapEdgeRenderOptions,
  MapFillRenderOptions,
  MapImageRenderOptions,
  MapImageRenderer,
  WgsPointRectSelector,
} from "../../api/maprender/index.js";

const DEFAULT_STYLE = Object.freeze({
  defaultColor: new Color(60, 160, 60, 255),
  zeroColor: new Color(0, 0, 255, 255),
  edgeColor: new Color(64, 64, 64, 255),
  selectedColor: new Color(245, 158, 11, 255),
  edgeWidth: 1,
  includeZero: true,
  drawEdge: true,
});

export class GaluchatLocalMapSource {
  constructor({
    mapsetReader,
    wordbookReader,
    renderer = new MapImageRenderer(),
    geocoder = null,
    formatPlaceName = defaultFormatPlaceName,
  } = {}) {
    if (mapsetReader == null) {
      throw new TypeError("mapsetReader is required");
    }
    if (wordbookReader == null) {
      throw new TypeError("wordbookReader is required");
    }
    this.mapsetReader = mapsetReader;
    this.wordbookReader = wordbookReader;
    this.renderer = renderer;
    this.geocoder = geocoder ?? new ReverseGeocoder(mapsetReader, wordbookReader);
    this.formatPlaceName = formatPlaceName;
  }

  get unitInvX() {
    return this.mapsetReader.unitInvX;
  }

  get unitInvY() {
    return this.mapsetReader.unitInvY;
  }

  getZoomLevelIndex() {
    return 0;
  }

  getZoomLevelCount() {
    return 1;
  }

  setZoomLevelIndex(index) {
    if (index !== 0) {
      throw new RangeError("single-level map source only supports zoom level 0");
    }
  }

  resolveZoomPixelScale(index = 0) {
    if (index !== 0) {
      throw new RangeError("single-level map source only supports zoom level 0");
    }
    return 1;
  }

  snapCenter(center) {
    return center;
  }

  render(center, width, height, options = {}) {
    const selector = new WgsPointRectSelector(center.lon, center.lat, width, height);
    const image = this.renderer.render(
      this.mapsetReader,
      selector,
      createMapImageRenderOptions(options.style, options.selectedCode ?? null),
    );
    return {
      image,
      rect: selector.resolveRect(this.mapsetReader),
    };
  }

  reverseGeocode(lon, lat) {
    return this.geocoder.reverseGeocode(lon, lat);
  }

  readCode(lon, lat) {
    return this.geocoder.readCode(lon, lat);
  }

  readPathByCode(code) {
    return this.wordbookReader.readStringSetByCode(code);
  }

  resolvePlace(code) {
    const path = this.readPathByCode(code);
    return {
      code,
      path,
      name: this.formatPlaceName(code, path),
    };
  }

  resolvePlaceAt(lon, lat) {
    const code = this.readCode(lon, lat);
    return {
      lon,
      lat,
      ...this.resolvePlace(code),
    };
  }
}

export function createMapImageRenderOptions(style = {}, selectedCode = null) {
  const effectiveStyle = { ...DEFAULT_STYLE, ...(style ?? {}) };
  const colors = {
    0: effectiveStyle.zeroColor,
  };
  if (selectedCode !== null && selectedCode > 0) {
    colors[selectedCode] = effectiveStyle.selectedColor;
  }
  return new MapImageRenderOptions({
    fillOptions: new MapFillRenderOptions({
      defaultColor: effectiveStyle.defaultColor,
      colors,
      colorResolver: effectiveStyle.colorResolver ?? null,
    }),
    edgeOptions: effectiveStyle.drawEdge
      ? new MapEdgeRenderOptions({
        edgeColor: effectiveStyle.edgeColor,
        edgeWidth: effectiveStyle.edgeWidth,
        includeZero: effectiveStyle.includeZero,
      })
      : null,
  });
}

function defaultFormatPlaceName(code, path) {
  if (code === null || code === undefined) {
    return "範囲外";
  }
  if (code === 0) {
    return "海上";
  }
  if (path === null) {
    return "所属不明地";
  }
  return formatAddressPath(path, { omitEmpty: true, separator: " " }) ?? "所属不明地";
}
