const PARAMETERS = new Map([
  [8, { runBits: 3, runMin: 2, baseValueBits: 2 }],
  [16, { runBits: 3, runMin: 2, baseValueBits: 2 }],
  [32, { runBits: 4, runMin: 4, baseValueBits: 3 }],
  [64, { runBits: 4, runMin: 4, baseValueBits: 4 }],
  [128, { runBits: 4, runMin: 4, baseValueBits: 4 }],
  [256, { runBits: 5, runMin: 4, baseValueBits: 4 }],
]);

export class ShortValueRleLenDecoder {
  constructor(resolution, valueBitsAdd, runBitsAdd) {
    const parameter = PARAMETERS.get(resolution);
    if (!Number.isInteger(valueBitsAdd) || valueBitsAdd < 0 || valueBitsAdd > 3) {
      throw new RangeError("valueBitsAdd must be in 0..3");
    }
    if (!Number.isInteger(runBitsAdd) || runBitsAdd < 0 || runBitsAdd > 1) {
      throw new RangeError("runBitsAdd must be in 0..1");
    }
    this.resolution = resolution;
    this.runBits = parameter ? parameter.runBits + runBitsAdd : null;
    this.runMin = parameter ? parameter.runMin : null;
    this.runMax = parameter ? parameter.runMin + (1 << this.runBits) - 1 : null;
    this.valueBits = parameter ? parameter.baseValueBits + valueBitsAdd : null;
  }

  readToken(reader, dest, limit) {
    const prefix = reader.readBitsAsInt32(1);
    if (prefix === 0) {
      if (limit < 1) {
        throw new Error("MBUInt token exceeds requested count");
      }
      dest[0] = reader.readMbUInt();
      return 1;
    }
    if (this.runBits === null) {
      throw new Error(`unsupported ShortValue resolution: ${this.resolution}`);
    }
    const run = reader.readBitsAsInt32(this.runBits) + this.runMin;
    if (run > this.runMax || run > limit) {
      throw new Error("invalid ShortValue run length");
    }
    for (let i = 0; i < run; i++) {
      dest[i] = reader.readBitsAsInt32(this.valueBits) + 1;
    }
    return run;
  }
}
