import { MapInteractionController } from "./MapInteractionController.js";

const DEFAULT_CENTER = Object.freeze({ lon: 140.0267, lat: 35.6810 });

export class GaluchatMapView extends EventTarget {
  constructor(canvas, source, options = {}) {
    super();
    if (canvas == null) {
      throw new TypeError("canvas is required");
    }
    if (source == null) {
      throw new TypeError("source is required");
    }
    this.canvas = canvas;
    this.source = source;
    this.center = normalizeLonLat(options.center ?? DEFAULT_CENTER);
    this.selectedCode = options.selectedCode ?? null;
    this.style = options.style ?? {};
    this.maxWidth = options.maxWidth ?? Infinity;
    this.maxHeight = options.maxHeight ?? Infinity;
    this.autoResize = options.autoResize ?? true;
    this.viewportElement = options.viewportElement ?? this.canvas;
    this.currentRect = null;
    this.currentPixelScale = 1;
    this.currentImageData = null;
    this.currentPlace = null;
    this.context = this.canvas.getContext("2d");
    this.interactionController = null;
    this.resizeObserver = null;

    if (options.interaction !== false) {
      this.setInteraction(options.interaction ?? true, {
        minDragPixels: options.minDragPixels,
      });
    }
    if (this.autoResize && typeof ResizeObserver !== "undefined") {
      this.resizeObserver = new ResizeObserver(() => this.render());
      this.resizeObserver.observe(this.viewportElement);
    }
  }

  setInteraction(interaction, options = {}) {
    if (this.interactionController === null) {
      this.interactionController = new MapInteractionController(
        this.canvas,
        {
          canStartDrag: () => this.currentRect !== null,
          onHover: (event) => this.handleHover(event),
          onDragPreview: (delta) => this.previewPan(delta.x, delta.y),
          onPan: (delta) => this.panBy(delta.x, delta.y),
          onSelect: (event) => this.selectAt(this.eventToCanvasPoint(event)),
          onZoomIn: (event) => this.zoomIn(this.eventToCanvasPoint(event)),
          onZoomOut: (event) => this.zoomOut(this.eventToCanvasPoint(event)),
        },
        {
          interaction,
          minDragPixels: options.minDragPixels,
        },
      );
    } else {
      this.interactionController.setInteraction(interaction);
    }
  }

  render() {
    const width = this.resolveCanvasWidth();
    const height = this.resolveCanvasHeight();
    if (this.viewportElement !== this.canvas) {
      this.canvas.style.width = `${width}px`;
      this.canvas.style.height = `${height}px`;
    }
    this.canvas.width = width;
    this.canvas.height = height;

    const rendered = this.source.render(this.center, width, height, {
      selectedCode: this.selectedCode,
      style: this.style,
    });
    if (rendered.center !== undefined) {
      this.center = normalizeLonLat(rendered.center);
    }
    this.currentRect = rendered.rect;
    this.currentPixelScale = rendered.pixelScale ?? 1;
    this.currentImageData = rendered.image.toImageData((imageWidth, imageHeight) => (
      this.context.createImageData(imageWidth, imageHeight)
    ));
    this.context.putImageData(this.currentImageData, 0, 0);
    this.updateCurrentPlace();
    this.dispatchMapRender(width, height);
  }

  setView({ center = this.center, selectedCode = this.selectedCode, style = this.style } = {}) {
    this.center = normalizeLonLat(center);
    this.selectedCode = selectedCode;
    this.style = style;
    return this.render();
  }

  setCenter(center) {
    return this.setView({ center });
  }

  setSelectedCode(selectedCode) {
    return this.setView({ selectedCode });
  }

  setStyle(style) {
    return this.setView({ style });
  }

  getZoomLevelIndex() {
    return this.source.getZoomLevelIndex();
  }

  getZoomLevelCount() {
    return this.source.getZoomLevelCount();
  }

  canZoomIn() {
    return this.getZoomLevelIndex() > 0;
  }

  canZoomOut() {
    return this.getZoomLevelIndex() < this.getZoomLevelCount() - 1;
  }

  zoomIn(anchorPoint = this.canvasCenterPoint()) {
    return this.setZoomLevel(this.getZoomLevelIndex() - 1, anchorPoint);
  }

  zoomOut(anchorPoint = this.canvasCenterPoint()) {
    return this.setZoomLevel(this.getZoomLevelIndex() + 1, anchorPoint);
  }

  setZoomLevel(index, anchorPoint = this.canvasCenterPoint()) {
    const levelCount = this.getZoomLevelCount();
    const currentIndex = this.getZoomLevelIndex();
    const nextIndex = clampIndex(index, levelCount);
    if (nextIndex === currentIndex) {
      return null;
    }
    let nextCenter = this.center;
    if (this.currentRect !== null) {
      const anchorX = clampPixelIndex(anchorPoint.x, this.canvas.width);
      const anchorY = clampPixelIndex(anchorPoint.y, this.canvas.height);
      const nextPixelScale = this.source.resolveZoomPixelScale(nextIndex);
      const baseX = this.currentRect.x + anchorX * this.currentPixelScale;
      const baseY = this.currentRect.y + (this.canvas.height - 1 - anchorY) * this.currentPixelScale;
      const centerX = baseX - anchorX * nextPixelScale + Math.floor(this.canvas.width * nextPixelScale / 2);
      const centerY = baseY - (this.canvas.height - 1 - anchorY) * nextPixelScale + Math.floor(this.canvas.height * nextPixelScale / 2);
      nextCenter = {
        lon: centerX / this.source.unitInvX,
        lat: centerY / this.source.unitInvY,
      };
    }
    this.source.setZoomLevelIndex(nextIndex);
    nextCenter = this.source.snapCenter(nextCenter, nextIndex);
    this.dispatchEvent(new CustomEvent("zoomchange", {
      detail: {
        zoomLevelIndex: nextIndex,
        zoomLevelCount: levelCount,
      },
    }));
    return this.setCenter(nextCenter);
  }

  panBy(deltaX, deltaY) {
    if (this.currentRect === null) {
      return null;
    }
    this.center = {
      lon: this.center.lon - deltaX * this.currentPixelScale / this.source.unitInvX,
      lat: this.center.lat + deltaY * this.currentPixelScale / this.source.unitInvY,
    };
    this.dispatchViewChange();
    return this.render();
  }

  previewPan(deltaX, deltaY) {
    if (this.currentImageData === null) {
      return;
    }
    this.context.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.context.putImageData(this.currentImageData, Math.round(deltaX), Math.round(deltaY));
  }

  selectAt(point) {
    if (this.currentRect === null) {
      return null;
    }
    const lonlat = this.canvasPointToLonLat(point.x, point.y);
    const result = this.source.reverseGeocode(lonlat.lon, lonlat.lat);
    this.selectedCode = result.code ?? null;
    const detail = {
      lon: lonlat.lon,
      lat: lonlat.lat,
      code: result.code,
      path: result.path,
      name: this.source.formatPlaceName(result.code, result.path),
      found: result.found,
    };
    this.dispatchEvent(new CustomEvent("select", { detail }));
    this.render();
    return detail;
  }

  clearSelection() {
    return this.setView({ selectedCode: null });
  }

  dispose() {
    this.resizeObserver?.disconnect();
    this.interactionController?.dispose();
  }

  handleHover(event) {
    if (this.currentRect === null) {
      return;
    }
    const point = this.eventToCanvasPoint(event);
    const lonlat = this.canvasPointToLonLat(point.x, point.y);
    const place = this.source.resolvePlaceAt(lonlat.lon, lonlat.lat);
    this.dispatchEvent(new CustomEvent("pointerplace", {
      detail: {
        lon: lonlat.lon,
        lat: lonlat.lat,
        ...place,
      },
    }));
  }

  updateCurrentPlace() {
    const code = this.selectedCode ?? this.source.readCode(this.center.lon, this.center.lat);
    const place = this.source.resolvePlace(code);
    this.currentPlace = place;
    this.dispatchEvent(new CustomEvent("placechange", {
      detail: {
        lon: this.center.lon,
        lat: this.center.lat,
        ...place,
      },
    }));
  }

  dispatchMapRender(width, height) {
    const detail = {
      center: this.center,
      lon: this.center.lon,
      lat: this.center.lat,
      rect: this.currentRect,
      width,
      height,
      pixelScale: this.currentPixelScale,
      zoomLevelIndex: this.source.getZoomLevelIndex(),
      zoomLevelCount: this.source.getZoomLevelCount(),
    };
    this.dispatchEvent(new CustomEvent("maprender", { detail }));
    this.dispatchViewChange();
  }

  dispatchViewChange() {
    this.dispatchEvent(new CustomEvent("viewchange", {
      detail: {
        center: this.center,
        lon: this.center.lon,
        lat: this.center.lat,
        selectedCode: this.selectedCode,
        zoomLevelIndex: this.source.getZoomLevelIndex(),
        zoomLevelCount: this.source.getZoomLevelCount(),
      },
    }));
  }

  eventToCanvasPoint(event) {
    const rect = this.canvas.getBoundingClientRect();
    return {
      x: (event.clientX - rect.left) * this.canvas.width / rect.width,
      y: (event.clientY - rect.top) * this.canvas.height / rect.height,
    };
  }

  canvasCenterPoint() {
    return {
      x: this.canvas.width / 2,
      y: this.canvas.height / 2,
    };
  }

  canvasPointToLonLat(x, y) {
    const pixelX = this.currentRect.x + clampPixelIndex(x, this.canvas.width) * this.currentPixelScale;
    const pixelY = this.currentRect.y + (this.canvas.height - 1 - clampPixelIndex(y, this.canvas.height)) * this.currentPixelScale;
    return {
      lon: pixelX / this.source.unitInvX,
      lat: pixelY / this.source.unitInvY,
    };
  }

  resolveCanvasWidth() {
    return clampPositiveInteger(
      this.viewportElement.clientWidth || this.canvas.clientWidth || this.canvas.width || 1,
      this.maxWidth,
    );
  }

  resolveCanvasHeight() {
    return clampPositiveInteger(
      this.viewportElement.clientHeight || this.canvas.clientHeight || this.canvas.height || 1,
      this.maxHeight,
    );
  }
}

export function normalizeLonLat(value) {
  if (!Number.isFinite(value.lon) || !Number.isFinite(value.lat)) {
    throw new TypeError("center must have finite lon and lat");
  }
  return { lon: value.lon, lat: value.lat };
}

export function clampPositiveInteger(value, maxValue) {
  const size = Math.floor(Math.min(value, maxValue));
  return Math.max(1, size);
}

export function clampPixelIndex(value, size) {
  return Math.min(Math.max(Math.floor(value), 0), size - 1);
}

export function clampIndex(index, count) {
  return Math.min(Math.max(Math.floor(index), 0), count - 1);
}
