import { BytesReader } from "../../io/BytesReader.js";
import { RawRaster } from "../../raster/RawRaster.js";
import { GaluchatImageDataChunk01Reader } from "../../chunk/gi01/GaluchatImageDataChunk01Reader.js";
import { WGSMapHeader } from "./WGSMapHeader.js";

export class GaluchatWGSMap3Reader {
  constructor(header, bytes, chunkOffset, width, height) {
    this.header = header;
    this.bytes = bytes;
    this.chunkOffset = chunkOffset;
    this.width = width;
    this.height = height;
  }

  static fromUint8Array(bytes) {
    const reader = new BytesReader(bytes);
    const header = new WGSMapHeader(reader);
    const chunkOffset = reader.pos;
    const chunk = new GaluchatImageDataChunk01Reader(reader);
    const { width, height } = chunk;
    chunk.skipToEnd();
    if (reader.pos !== reader.end) {
      throw new Error("WGSMap/3 has trailing bytes");
    }
    return new GaluchatWGSMap3Reader(header, bytes, chunkOffset, width, height);
  }

  get unitInvX() { return this.header.unitInvX; }
  get unitInvY() { return this.header.unitInvY; }

  get area() {
    return { x: this.header.west, y: this.header.south, width: this.width, height: this.height };
  }

  get areaOfWgs() {
    const area = this.area;
    return {
      x: area.x / this.header.unitInvX,
      y: area.y / this.header.unitInvY,
      width: area.width / this.header.unitInvX,
      height: area.height / this.header.unitInvY,
    };
  }

  readPoint(x, y) {
    if (x < 0 || x >= this.width || y < 0 || y >= this.height) return null;
    const reader = new BytesReader(this.bytes, this.chunkOffset);
    return new GaluchatImageDataChunk01Reader(reader).readPoint(x, y);
  }

  readWgsPoint(ix, iy) {
    return this.readPoint(ix - this.header.west, iy - this.header.south);
  }

  readWgsPointf(lon, lat) {
    return this.readPoint(
      Math.round(lon * this.header.unitInvX) - this.header.west,
      Math.round(lat * this.header.unitInvY) - this.header.south,
    );
  }

  readRect(x, y, width, height) {
    const raster = new RawRaster(width, height);
    const reader = new BytesReader(this.bytes, this.chunkOffset);
    new GaluchatImageDataChunk01Reader(reader).readRect(x, y, raster);
    return raster;
  }

  readWgsRect(rect) {
    return this.readRect(
      rect.x - this.header.west,
      rect.y - this.header.south,
      rect.width,
      rect.height,
    );
  }

  readWgsRectf(rect) {
    return this.readWgsRect({
      x: Math.round(rect.x * this.header.unitInvX),
      y: Math.round(rect.y * this.header.unitInvY),
      width: Math.round(rect.width * this.header.unitInvX),
      height: Math.round(rect.height * this.header.unitInvY),
    });
  }

  toRaster() { return this.readRect(0, 0, this.width, this.height); }
}
