const D_FORMATS = [
  { bits: 2, minimum: -1 },
  { bits: 3, minimum: -3 },
  { bits: 4, minimum: -7 },
];
const RUN_COUNT_BITS = 5;
const MIN_RUN_COUNT = 2;
const SUPPORTED_RESOLUTIONS = new Set([8, 16, 32, 64, 128, 256]);

export class SingleEdgeRowLenDecoder {
  constructor(resolution, dValueFormat, mbuintReduceBits) {
    if (dValueFormat < 0 || dValueFormat >= D_FORMATS.length) {
      throw new Error("invalid SingleEdge d value format");
    }
    if (mbuintReduceBits !== null && mbuintReduceBits !== undefined
      && (!Number.isInteger(mbuintReduceBits) || mbuintReduceBits < 1 || mbuintReduceBits > 8)) {
      throw new RangeError("mbuintReduceBits must be in 1..8");
    }
    this.resolution = resolution;
    this.dFormat = D_FORMATS[dValueFormat];
    this.mbuintReduceBits = mbuintReduceBits;
  }

  hasMbUIntReduce() {
    return this.mbuintReduceBits !== null && this.mbuintReduceBits !== undefined;
  }

  readToken(reader, dest, limit) {
    const prefix = reader.readBitsAsInt32(1);
    if (prefix === 0) {
      if (limit < 1) {
        throw new Error("MBUInt token exceeds requested count");
      }
      dest[0] = reader.readMbUInt();
      return 1;
    }
    return this._readSingleEdgeToken(reader, dest, limit);
  }

  readReducedMiddleToken(reader, dest, limit) {
    const prefix = reader.readBitsAsInt32(1);
    if (prefix === 0) {
      if (!this.hasMbUIntReduce()) {
        throw new Error("MBUIntReduce is disabled");
      }
      if (limit < 1) {
        throw new Error("short MBUInt token exceeds requested count");
      }
      dest[0] = reader.readBitsAsInt32(this.mbuintReduceBits) + 1;
      return 1;
    }
    return this._readSingleEdgeToken(reader, dest, limit);
  }

  _readSingleEdgeToken(reader, dest, limit) {
    if (!SUPPORTED_RESOLUTIONS.has(this.resolution)) {
      throw new Error(`unsupported SingleEdgeRow resolution: ${this.resolution}`);
    }
    const runCount = reader.readBitsAsInt32(RUN_COUNT_BITS) + MIN_RUN_COUNT;
    if (runCount > limit) {
      throw new Error("single edge token exceeds requested count");
    }
    let previous = reader.readMbUInt();
    if (previous <= 0) {
      throw new Error("invalid single edge value");
    }
    dest[0] = previous;
    for (let i = 1; i < runCount; i++) {
      const dValue = reader.readBitsAsInt32(this.dFormat.bits) + this.dFormat.minimum;
      const value = 2 * this.resolution - previous + dValue;
      if (value <= 0) {
        throw new Error("invalid single edge value");
      }
      dest[i] = value;
      previous = value;
    }
    return runCount;
  }
}
