const MUINT2_BASE = 252;
const MUINT3_BASE = MUINT2_BASE + 0xff + 1;
const MUINT4_BASE = MUINT3_BASE + 0xffff + 1;
const MUINT5_BASE = MUINT4_BASE + 0xffffff + 1;
const UINT32_MAX = 0xffffffff;

const MINT2_BASE = 124;
const MINT3_BASE = MINT2_BASE + 0xff + 1;
const MINT4_BASE = MINT3_BASE + 0xffff + 1;
const MINT5_BASE = MINT4_BASE + 0xffffff + 1;

export class BitReader {
  constructor() {
    this.bitLeft = 0;
    this.bitCache = 0;
  }

  getBitOffset() {
    return this.bitLeft;
  }

  readBitsAsInt32(bits) {
    if (bits < 0 || bits > 31) {
      throw new RangeError("bits must be in 0..31");
    }
    if (bits === 0) {
      return 0;
    }
    let result = 0;
    let remaining = bits;

    if (this.bitLeft > 0) {
      const readBits = Math.min(this.bitLeft, remaining);
      result = (this.bitCache >> (this.bitLeft - readBits)) & ((1 << readBits) - 1);
      this.bitLeft -= readBits;
      remaining -= readBits;
      this.bitCache = this.bitLeft > 0 ? this.bitCache & ((1 << this.bitLeft) - 1) : 0;
    }

    while (remaining >= 8) {
      result = (result << 8) | this._nextByte();
      remaining -= 8;
    }

    if (remaining > 0) {
      const nextByte = this._nextByte();
      result = (result << remaining) | (nextByte >> (8 - remaining));
      this.bitLeft = 8 - remaining;
      this.bitCache = nextByte & ((1 << this.bitLeft) - 1);
    }
    return result;
  }

  readByte() {
    const left = this.bitLeft;
    const nextByte = this._nextByte();
    if (left === 0) {
      return nextByte;
    }
    const merged = (this.bitCache << 8) | nextByte;
    const result = (merged >> left) & 0xff;
    this.bitCache = merged & ((1 << left) - 1);
    return result;
  }

  readMbUInt() {
    const prefix = this.readByte();
    if (prefix < MUINT2_BASE) {
      return prefix;
    }
    if (prefix === 255) {
      return MUINT2_BASE + this.readByte();
    }
    if (prefix === 254) {
      return MUINT3_BASE + (this.readByte() << 8) + this.readByte();
    }
    if (prefix === 253) {
      return MUINT4_BASE + (this.readByte() << 16) + (this.readByte() << 8) + this.readByte();
    }
    if (prefix === 252) {
      const value = this.readByte() * 0x1000000 + (this.readByte() << 16) + (this.readByte() << 8) + this.readByte();
      if (value > UINT32_MAX - MUINT5_BASE) {
        throw new RangeError("MBUInt exceeds Uint32 range");
      }
      return MUINT5_BASE + value;
    }
    throw new Error("invalid MBUInt prefix");
  }

  readMbInt() {
    const head = this.readByte();
    const sign = (head & 0x80) !== 0 ? -1 : 1;
    const prefix = head & 0x7f;
    let value;
    if (prefix < MINT2_BASE) {
      value = prefix;
    } else if (prefix === 127) {
      value = MINT2_BASE + this.readByte();
    } else if (prefix === 126) {
      value = MINT3_BASE + (this.readByte() << 8) + this.readByte();
    } else if (prefix === 125) {
      value = MINT4_BASE + (this.readByte() << 16) + (this.readByte() << 8) + this.readByte();
    } else if (prefix === 124) {
      value = MINT5_BASE + this.readByte() * 0x1000000 + (this.readByte() << 16) + (this.readByte() << 8) + this.readByte();
    } else {
      throw new Error("invalid MBInt prefix");
    }
    return sign * value;
  }

  skipToByte() {
    const skipped = this.bitLeft;
    this.bitLeft = 0;
    this.bitCache = 0;
    return skipped;
  }
}

export class BytesReader extends BitReader {
  constructor(bytes, offset = 0, length = bytes.length - offset) {
    super();
    if (!(bytes instanceof Uint8Array)) {
      throw new TypeError("BytesReader requires Uint8Array");
    }
    if (offset < 0 || length < 0 || offset + length > bytes.length) {
      throw new RangeError("invalid BytesReader range");
    }
    this.bytes = bytes;
    this.pos = offset;
    this.end = offset + length;
  }

  _nextByte() {
    if (this.pos >= this.end) {
      throw new RangeError("unexpected end of byte stream");
    }
    return this.bytes[this.pos++];
  }

  readAsBytes(length) {
    if (length < 0) {
      throw new RangeError("length must be non-negative");
    }
    if (this.bitLeft === 0) {
      if (this.pos + length > this.end) {
        throw new RangeError("unexpected end of byte stream");
      }
      const result = this.bytes.subarray(this.pos, this.pos + length);
      this.pos += length;
      return result;
    }
    const result = new Uint8Array(length);
    for (let i = 0; i < length; i++) {
      result[i] = this.readByte();
    }
    return result;
  }

  readBytesAsBStr(fieldSize) {
    const raw = this.readAsBytes(fieldSize);
    let end = raw.length;
    while (end > 0 && raw[end - 1] === 0) {
      end--;
    }
    return raw.subarray(0, end);
  }

  readBStrAscii(fieldSize) {
    const raw = this.readBytesAsBStr(fieldSize);
    let text = "";
    for (let i = 0; i < raw.length; i++) {
      text += String.fromCharCode(raw[i]);
    }
    return text;
  }

  readAscii(length) {
    const raw = this.readAsBytes(length);
    let text = "";
    for (let i = 0; i < raw.length; i++) {
      text += String.fromCharCode(raw[i]);
    }
    return text;
  }

  skipBits(bitCount) {
    if (bitCount < 0) {
      throw new RangeError("bitCount must be non-negative");
    }
    if (bitCount === 0) {
      return;
    }

    if (this.bitLeft > 0) {
      const consumed = Math.min(this.bitLeft, bitCount);
      this.bitLeft -= consumed;
      bitCount -= consumed;
      this.bitCache = this.bitLeft > 0 ? this.bitCache & ((1 << this.bitLeft) - 1) : 0;
      if (bitCount === 0) {
        return;
      }
    }

    const byteCount = Math.floor(bitCount / 8);
    if (byteCount > 0) {
      if (this.pos + byteCount > this.end) {
        throw new RangeError("unexpected end of byte stream");
      }
      this.pos += byteCount;
      bitCount -= byteCount * 8;
    }

    if (bitCount > 0) {
      const nextByte = this._nextByte();
      this.bitLeft = 8 - bitCount;
      this.bitCache = nextByte & ((1 << this.bitLeft) - 1);
    }
  }

  skipInByte(length) {
    if (length < 0) {
      throw new RangeError("length must be non-negative");
    }
    if (length === 0) {
      return;
    }
    if (this.bitLeft === 0) {
      if (this.pos + length > this.end) {
        throw new RangeError("unexpected end of byte stream");
      }
      this.pos += length;
      return;
    }
    if (length > 1) {
      if (this.pos + length - 1 > this.end) {
        throw new RangeError("unexpected end of byte stream");
      }
      this.pos += length - 1;
    }
    this.readByte();
  }

}

export function bitWidthForPaletteSize(size) {
  if (size <= 2) {
    return 1;
  }
  if (size <= 4) {
    return 2;
  }
  if (size <= 16) {
    return 4;
  }
  if (size <= 256) {
    return 8;
  }
  throw new Error("unsupported palette size");
}
