import { BytesReader } from "../../io/BytesReader.js";
import { RawRaster } from "../../raster/RawRaster.js";
import { GaluchatImageDataChunk01Reader } from "../../chunk/gi01/GaluchatImageDataChunk01Reader.js";
import { WGSMapSetHeader3 } from "./WGSMapSetHeader3.js";

export class GaluchatWGSMapSet3Reader {
  constructor(header, bytes, chunkOffset, area) {
    this.header = header;
    this.bytes = bytes;
    this.chunkOffset = chunkOffset;
    this._area = area;
  }

  static fromUint8Array(bytes) {
    const reader = new BytesReader(bytes);
    const header = new WGSMapSetHeader3(reader);
    let chunkOffset = reader.pos;
    let name = reader.readAscii(4);
    if (name === "LAYO") {
      reader.skipInByte(reader.readMbUInt());
      chunkOffset = reader.pos;
      name = reader.readAscii(4);
    }
    if (name !== "GI01") throw new Error("WGSMapSet/3 does not contain a GI01 chunk");

    const validationReader = new BytesReader(bytes, chunkOffset);
    let left = null;
    let top = null;
    let right = null;
    let bottom = null;
    for (const origin of header.mapSet) {
      const chunk = new GaluchatImageDataChunk01Reader(validationReader);
      left = left === null ? origin.west : Math.min(left, origin.west);
      top = top === null ? origin.south : Math.min(top, origin.south);
      right = right === null ? origin.west + chunk.width : Math.max(right, origin.west + chunk.width);
      bottom = bottom === null ? origin.south + chunk.height : Math.max(bottom, origin.south + chunk.height);
      chunk.skipToEnd();
    }
    if (validationReader.pos !== validationReader.end) {
      throw new Error("WGSMapSet/3 has trailing bytes");
    }
    const area = { x: left, y: top, width: right - left, height: bottom - top };
    return new GaluchatWGSMapSet3Reader(header, bytes, chunkOffset, area);
  }

  get unitInvX() { return this.header.unitInvX; }
  get unitInvY() { return this.header.unitInvY; }
  get numOfMaps() { return this.header.numOfMaps; }
  get area() { return this._area; }

  get areaOfWgs() {
    return {
      x: this._area.x / this.header.unitInvX,
      y: this._area.y / this.header.unitInvY,
      width: this._area.width / this.header.unitInvX,
      height: this._area.height / this.header.unitInvY,
    };
  }

  readWgsPoint(ix, iy) {
    let zeroHit = null;
    const reader = new BytesReader(this.bytes, this.chunkOffset);
    for (const origin of this.header.mapSet) {
      const chunk = new GaluchatImageDataChunk01Reader(reader);
      if (ix < origin.west || iy < origin.south
        || ix >= origin.west + chunk.width || iy >= origin.south + chunk.height) {
        chunk.skipToEnd();
        continue;
      }
      const value = chunk.readPoint(ix - origin.west, iy - origin.south);
      chunk.skipToEnd();
      if (value !== 0) return value;
      zeroHit = 0;
    }
    return zeroHit;
  }

  readWgsPointf(lon, lat) {
    return this.readWgsPoint(
      Math.round(lon * this.header.unitInvX),
      Math.round(lat * this.header.unitInvY),
    );
  }

  readRect(x, y, width, height) {
    return this.readWgsRect({ x: this._area.x + x, y: this._area.y + y, width, height });
  }

  readWgsRect(target) {
    const dest = new RawRaster(target.width, target.height);
    const reader = new BytesReader(this.bytes, this.chunkOffset);
    for (const origin of this.header.mapSet) {
      const chunk = new GaluchatImageDataChunk01Reader(reader);
      const crossed = crossRect(
        { x: origin.west, y: origin.south, width: chunk.width, height: chunk.height },
        target,
      );
      if (crossed === null) {
        chunk.skipToEnd();
        continue;
      }
      const temp = new RawRaster(crossed.width, crossed.height);
      chunk.readRect(crossed.x - origin.west, crossed.y - origin.south, temp);
      chunk.skipToEnd();
      for (let y = 0; y < crossed.height; y++) {
        for (let x = 0; x < crossed.width; x++) {
          const value = temp.get(x, y);
          if (value !== 0) dest.set(crossed.x - target.x + x, crossed.y - target.y + y, value);
        }
      }
    }
    return dest;
  }

  readWgsRectf(rect) {
    return this.readWgsRect({
      x: Math.round(rect.x * this.header.unitInvX),
      y: Math.round(rect.y * this.header.unitInvY),
      width: Math.round(rect.width * this.header.unitInvX),
      height: Math.round(rect.height * this.header.unitInvY),
    });
  }

  toRaster() { return this.readWgsRect(this._area); }
}

function crossRect(a, b) {
  const x = Math.max(a.x, b.x);
  const y = Math.max(a.y, b.y);
  const right = Math.min(a.x + a.width, b.x + b.width);
  const bottom = Math.min(a.y + a.height, b.y + b.height);
  return x < right && y < bottom ? { x, y, width: right - x, height: bottom - y } : null;
}
