export const CONTAINER_TYPE_MIXED = 0;
export const CONTAINER_TYPE_VALUES = 1;
export const CONTAINER_TYPE_MONO = 2;
export const CONTAINER_TYPE_RESERVED = 3;

export const PALLET_1BIT = 0;
export const PALLET_2BIT = 1;
export const PALLET_4BIT = 2;
export const PALLET_NBIT = 3;

export const RLE_PALLET_2 = 0;
export const RLE_PALLET_3 = 1;
export const RLE_PALLET_5 = 2;
export const RLE_PALLET_16 = 3;

export const RLE_DATA_ENCODING_MBUINT = 0;
export const RLE_DATA_ENCODING_SHORT_VALUE = 1;
export const RLE_DATA_ENCODING_SINGLE_EDGE_ROW = 2;

export const RLE_MODE_ZIGZAG = 0;
export const RLE_MODE_ZIGZAG_MH = 1;
export const RLE_MODE_ZIGZAG_T = 2;
export const RLE_MODE_ZIGZAG_T_MV = 3;

export class CellHeader {
  constructor(byte1) {
    if (byte1 < 0 || byte1 > 0xff) {
      throw new RangeError("invalid CellHeader byte");
    }
    this.byte1 = byte1;
  }

  isNode() {
    return ((this.byte1 >> 6) & 0x03) === 0;
  }

  isRaw() {
    return ((this.byte1 >> 6) & 0x03) === 1;
  }

  isRle() {
    return ((this.byte1 >> 6) & 0x03) === 2;
  }

  palletResolution() {
    if (!this.isRaw() && !this.isRle()) {
      throw new Error("CellHeader is not a data node");
    }
    return (this.byte1 >> 4) & 0x03;
  }

  numOfPallet() {
    if (this.isNode()) {
      return bitCount4(this.updatePalletTable4());
    }
    const resolution = this.palletResolution();
    if (this.isRle()) {
      return [2, 3, 5, 16][resolution];
    }
    if (resolution === PALLET_NBIT) {
      return null;
    }
    return [2, 4, 16][resolution];
  }

  rawUpdatePalletTableLow4() {
    if (!this.isRaw()) {
      throw new Error("CellHeader is not RAW");
    }
    return this.byte1 & 0x0f;
  }

  hasValidRawReservedBits() {
    if (!this.isRaw()) {
      throw new Error("CellHeader is not RAW");
    }
    if (this.palletResolution() === PALLET_NBIT) {
      return this.rawUpdatePalletTableLow4() === 0;
    }
    if (this.palletResolution() === PALLET_1BIT) {
      return this.rawUpdatePalletTableLow4() < 0x04;
    }
    return true;
  }

  rleMode() {
    if (!this.isRle()) {
      throw new Error("CellHeader is not RLE");
    }
    return this.byte1 & 0x03;
  }

  rleDataEncoding() {
    if (!this.isRle()) {
      throw new Error("CellHeader is not RLE");
    }
    return (this.byte1 >> 2) & 0x03;
  }

  hasValidRleReservedBits() {
    if (!this.isRle()) {
      throw new Error("CellHeader is not RLE");
    }
    const encoding = this.rleDataEncoding();
    return encoding === RLE_DATA_ENCODING_MBUINT
      || encoding === RLE_DATA_ENCODING_SHORT_VALUE
      || encoding === RLE_DATA_ENCODING_SINGLE_EDGE_ROW;
  }

  containerType() {
    if (!this.isNode()) {
      throw new Error("CellHeader is not Container");
    }
    return (this.byte1 >> 4) & 0x03;
  }

  updatePalletTable4() {
    if (!this.isNode()) {
      throw new Error("CellHeader is not Container");
    }
    return this.byte1 & 0x0f;
  }

  hasValidContainerHeader() {
    if (!this.isNode()) {
      throw new Error("CellHeader is not Container");
    }
    const type = this.containerType();
    const updateTable = this.updatePalletTable4();
    return type !== CONTAINER_TYPE_RESERVED
      && (type !== CONTAINER_TYPE_MIXED || (updateTable & 0x01) === 0)
      && (type !== CONTAINER_TYPE_MONO || (updateTable & 0x07) === 0);
  }
}

function bitCount4(value) {
  value &= 0x0f;
  return ((value >> 0) & 1) + ((value >> 1) & 1) + ((value >> 2) & 1) + ((value >> 3) & 1);
}
