import { BitReader } from "../../io/BytesReader.js";

class CleanLzssEnd extends RangeError {}

/** Incremental decoder over a size-bounded compressed BytesReader. */
export class LzssByteReader {
  constructor(sourceReader, windowSize = 256) {
    if (!Number.isInteger(windowSize) || windowSize <= 0) {
      throw new RangeError("windowSize must be a positive integer");
    }
    this.source = sourceReader;
    this.window = new Uint8Array(windowSize);
    this.ptr = 0;
    this.mode = 0;
    this.remaining = 0;
    this.refOffset = 0;
    this.finished = false;
  }

  readByte() {
    while (true) {
      if (this.remaining > 0) {
        let value;
        if (this.mode === 1) {
          try {
            value = this.source.readByte();
          } catch (error) {
            if (error instanceof RangeError) {
              throw new Error("truncated LZSS payload", { cause: error });
            }
            throw error;
          }
        } else {
          value = this.window[(this.ptr + this.refOffset) % this.window.length];
        }
        this._push(value);
        this.remaining--;
        if (this.remaining === 0) this.mode = 0;
        return value;
      }
      this._startToken();
    }
  }

  assertEnd() {
    try {
      this.readByte();
    } catch (error) {
      if (error instanceof CleanLzssEnd) return;
      throw error;
    }
    throw new Error("GI01 block payload has trailing bytes");
  }

  _startToken() {
    if (this.finished) throw new CleanLzssEnd("end of LZSS stream");
    const bits = remainingBits(this.source);
    if (bits <= 7) {
      if (bits > 0 && this.source.readBitsAsInt32(bits) !== 0) {
        throw new Error("invalid non-zero LZSS padding");
      }
      this.finished = true;
      throw new CleanLzssEnd("end of LZSS stream");
    }
    try {
      const flag = this.source.readBitsAsInt32(1);
      if (flag === 0) {
        this.remaining = this.source.readBitsAsInt32(4) + 1;
        this.mode = 1;
      } else {
        this.refOffset = this.source.readByte();
        this.remaining = this.source.readBitsAsInt32(4) + 2;
        this.mode = 2;
      }
    } catch (error) {
      if (error instanceof RangeError) {
        throw new Error("truncated LZSS payload", { cause: error });
      }
      throw error;
    }
  }

  _push(value) {
    this.window[this.ptr] = value & 0xff;
    this.ptr = (this.ptr + 1) % this.window.length;
  }
}

/** Bit/variable-integer reader over incrementally decoded LZSS bytes. */
export class IteratorByteReader extends BitReader {
  constructor(byteReader) {
    super();
    this.byteReader = byteReader;
    this.pos = 0;
  }

  _nextByte() {
    const value = this.byteReader.readByte();
    this.pos++;
    return value;
  }
}

function remainingBits(reader) {
  return (reader.end - reader.pos) * 8 + reader.getBitOffset();
}
