export class RawRaster {
  constructor(width, height, data = null) {
    if (width < 0 || height < 0) {
      throw new RangeError("invalid raster size");
    }
    this.width = width;
    this.height = height;
    const size = width * height;
    this.data = data === null ? new Uint32Array(size) : toUint32Array(data, size);
    if (this.data.length < size) {
      throw new RangeError("raster data is too short");
    }
  }

  get(x, y) {
    return this.data[x + y * this.width];
  }

  set(x, y, value) {
    validateUint32(value);
    this.data[x + y * this.width] = value;
  }
}

function toUint32Array(data, size) {
  if (data instanceof Uint32Array) {
    return data;
  }
  if (data.length < size) {
    throw new RangeError("raster data is too short");
  }
  const result = new Uint32Array(data.length);
  for (let i = 0; i < data.length; i++) {
    validateUint32(data[i]);
    result[i] = data[i];
  }
  return result;
}

function validateUint32(value) {
  if (!Number.isInteger(value) || value < 0 || value > 0xffffffff) {
    throw new RangeError("raster value exceeds Uint32 range");
  }
}
