import {
  RLE_MODE_ZIGZAG,
  RLE_MODE_ZIGZAG_MH,
  RLE_MODE_ZIGZAG_T,
  RLE_MODE_ZIGZAG_T_MV,
} from "./CellHeader.js";

export function mapIndex(resolution, mode, index) {
  if (mode === RLE_MODE_ZIGZAG) {
    return zigzag(resolution, index);
  }
  if (mode === RLE_MODE_ZIGZAG_MH) {
    return zigzag(resolution, mirrorX(resolution, index));
  }
  if (mode === RLE_MODE_ZIGZAG_T) {
    return transpose(resolution, zigzag(resolution, index));
  }
  if (mode === RLE_MODE_ZIGZAG_T_MV) {
    return transpose(resolution, zigzag(resolution, mirrorY(resolution, index)));
  }
  throw new Error("invalid RLE scan mode");
}

export function unmapIndex(resolution, mode, index) {
  if (mode === RLE_MODE_ZIGZAG) {
    return zigzag(resolution, index);
  }
  if (mode === RLE_MODE_ZIGZAG_MH) {
    return mirrorX(resolution, zigzag(resolution, index));
  }
  if (mode === RLE_MODE_ZIGZAG_T) {
    return zigzag(resolution, transpose(resolution, index));
  }
  if (mode === RLE_MODE_ZIGZAG_T_MV) {
    return mirrorY(resolution, zigzag(resolution, transpose(resolution, index)));
  }
  throw new Error("invalid RLE scan mode");
}

function zigzag(size, index) {
  const y = Math.floor(index / size);
  const x = index % size;
  return y % 2 === 0 ? x + y * size : (size - 1) + y * size - x;
}

function mirrorX(size, index) {
  const x = index % size;
  const y = Math.floor(index / size);
  return (size - 1 - x) + y * size;
}

function mirrorY(size, index) {
  const x = index % size;
  const y = Math.floor(index / size);
  return x + (size - 1 - y) * size;
}

function transpose(size, index) {
  const x = Math.floor(index / size);
  const y = index % size;
  return x + y * size;
}
