const DEFAULT_INTERACTION = Object.freeze({
  dragPan: true,
  wheelZoom: true,
  clickSelect: true,
  hoverStatus: true,
  contextMenu: false,
});

export class MapInteractionController {
  constructor(canvas, callbacks = {}, options = {}) {
    if (canvas == null) {
      throw new TypeError("canvas is required");
    }
    this.canvas = canvas;
    this.callbacks = callbacks;
    this.minDragPixels = options.minDragPixels ?? 4;
    this.interaction = normalizeInteraction(options.interaction ?? true);
    this.drag = null;
    this.listeners = [];
    this.bindEvents();
  }

  setInteraction(interaction) {
    this.interaction = normalizeInteraction(interaction);
  }

  dispose() {
    for (const { type, listener, options } of this.listeners) {
      this.canvas.removeEventListener(type, listener, options);
    }
    this.listeners = [];
    this.drag = null;
  }

  bindEvents() {
    this.listen("pointerdown", (event) => this.startDrag(event));
    this.listen("pointermove", (event) => this.movePointer(event));
    this.listen("pointerup", (event) => this.finishPointer(event));
    this.listen("pointercancel", (event) => this.cancelDrag(event));
    this.listen("wheel", (event) => this.handleWheel(event), { passive: false });
    this.listen("contextmenu", (event) => {
      if (!this.interaction.contextMenu) {
        event.preventDefault();
      }
    });
  }

  listen(type, listener, options = undefined) {
    this.canvas.addEventListener(type, listener, options);
    this.listeners.push({ type, listener, options });
  }

  startDrag(event) {
    if (!this.interaction.dragPan && !this.interaction.clickSelect) {
      return;
    }
    if (typeof this.callbacks.canStartDrag === "function" && !this.callbacks.canStartDrag(event)) {
      return;
    }
    this.canvas.setPointerCapture(event.pointerId);
    this.canvas.classList.add("dragging");
    this.drag = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      lastX: 0,
      lastY: 0,
      moved: false,
    };
    this.callbacks.onDragStart?.(event);
  }

  movePointer(event) {
    if (this.drag === null || this.drag.pointerId !== event.pointerId) {
      if (this.interaction.hoverStatus) {
        this.callbacks.onHover?.(event);
      }
      return;
    }
    const moveX = event.clientX - this.drag.startX;
    const moveY = event.clientY - this.drag.startY;
    this.drag.lastX = moveX;
    this.drag.lastY = moveY;
    this.drag.moved = this.drag.moved || Math.hypot(moveX, moveY) >= this.minDragPixels;
    if (this.drag.moved && this.interaction.dragPan) {
      this.callbacks.onDragPreview?.({ x: moveX, y: moveY }, event);
    }
  }

  finishPointer(event) {
    if (this.drag === null || this.drag.pointerId !== event.pointerId) {
      return;
    }
    const finishedDrag = this.drag;
    this.cancelDrag(event);
    if (finishedDrag.moved) {
      if (this.interaction.dragPan) {
        this.callbacks.onPan?.({ x: finishedDrag.lastX, y: finishedDrag.lastY }, event);
      }
      return;
    }
    if (this.interaction.clickSelect) {
      this.callbacks.onSelect?.(event);
    }
  }

  cancelDrag(event) {
    if (this.drag !== null && this.canvas.hasPointerCapture(this.drag.pointerId)) {
      this.canvas.releasePointerCapture(this.drag.pointerId);
    }
    this.canvas.classList.remove("dragging");
    this.drag = null;
    this.callbacks.onDragCancel?.(event);
  }

  handleWheel(event) {
    if (!this.interaction.wheelZoom || event.deltaY === 0) {
      return;
    }
    event.preventDefault();
    if (event.deltaY > 0) {
      this.callbacks.onZoomOut?.(event);
    } else {
      this.callbacks.onZoomIn?.(event);
    }
  }
}

function normalizeInteraction(interaction) {
  if (interaction === false || interaction === null) {
    return {
      dragPan: false,
      wheelZoom: false,
      clickSelect: false,
      hoverStatus: false,
      contextMenu: false,
    };
  }
  if (interaction === true || interaction === undefined) {
    return { ...DEFAULT_INTERACTION };
  }
  return {
    ...DEFAULT_INTERACTION,
    ...interaction,
  };
}
