import {
  RLE_DATA_ENCODING_MBUINT,
  RLE_DATA_ENCODING_SHORT_VALUE,
  RLE_DATA_ENCODING_SINGLE_EDGE_ROW,
  RLE_PALLET_2,
  RLE_PALLET_3,
  RLE_PALLET_5,
  RLE_PALLET_16,
} from "./CellHeader.js";
import { ShortValueRleLenDecoder } from "./rlelencodec/ShortValueRleLenDecoder.js";
import { SingleEdgeRowLenDecoder } from "./rlelencodec/SingleEdgeRowLenDecoder.js";

export function iterRunsUntil(reader, resolution, palletMode, initialIndex, dataEncoding, valueBitsAdd, consumer) {
  const pixels = resolution * resolution;
  let runIndex = 0;
  let previousIndex = null;
  let total = 0;

  if (dataEncoding === RLE_DATA_ENCODING_MBUINT) {
    while (total < pixels) {
      const count = reader.readMbUInt();
      if (count <= 0) {
        throw new Error("RLE count must be positive");
      }
      total += count;
      if (total > pixels) {
        throw new Error("RLE count total exceeds resolution");
      }
      const palletIndex = readNextIndex(reader, palletMode, initialIndex, runIndex, previousIndex);
      previousIndex = palletIndex;
      runIndex++;
      if (consumer(count, palletIndex) === false) {
        return false;
      }
    }
    return true;
  }

  if (dataEncoding === RLE_DATA_ENCODING_SHORT_VALUE) {
    const codec = new ShortValueRleLenDecoder(resolution, shortValueBitsAdd(valueBitsAdd), shortValueRunBitsAdd(valueBitsAdd));
    const runCount = reader.readMbUInt();
    if (runCount <= 0) {
      throw new Error("ShortValue requires at least one value");
    }
    const explicitCount = runCount - 1;
    const tokenBuffer = new Array(67);
    while (runIndex < explicitCount) {
      const tokenCount = codec.readToken(reader, tokenBuffer, explicitCount - runIndex);
      for (let i = 0; i < tokenCount; i++) {
        const count = tokenBuffer[i];
        total += count;
        if (count <= 0 || total >= pixels) {
          throw new Error("invalid RLE count total");
        }
        const palletIndex = readNextIndex(reader, palletMode, initialIndex, runIndex, previousIndex);
        previousIndex = palletIndex;
        runIndex++;
        if (consumer(count, palletIndex) === false) {
          return false;
        }
      }
    }
    const last = pixels - total;
    if (last <= 0) {
      throw new Error("RLE count total does not leave final run");
    }
    return consumer(last, readNextIndex(reader, palletMode, initialIndex, runIndex, previousIndex)) !== false;
  }

  if (dataEncoding === RLE_DATA_ENCODING_SINGLE_EDGE_ROW) {
    const codec = new SingleEdgeRowLenDecoder(resolution, singleEdgeDValueFormat(valueBitsAdd), singleEdgeMbUIntReduceBits(valueBitsAdd));
    const runCount = reader.readMbUInt();
    if (runCount < 2) {
      throw new Error("SingleEdgeRow requires at least two values");
    }
    const explicitCount = runCount - 1;
    const tokenBuffer = new Array(67);
    if (codec.hasMbUIntReduce()) {
      const first = reader.readMbUInt();
      if (first <= 0) {
        throw new Error("RLE count must be positive");
      }
      total += first;
      if (total >= pixels) {
        throw new Error("RLE count total exceeds pixel count");
      }
      let palletIndex = readNextIndex(reader, palletMode, initialIndex, runIndex, previousIndex);
      previousIndex = palletIndex;
      runIndex++;
      if (consumer(first, palletIndex) === false) {
        return false;
      }
      while (runIndex < explicitCount) {
        const tokenCount = codec.readReducedMiddleToken(reader, tokenBuffer, explicitCount - runIndex);
        for (let i = 0; i < tokenCount; i++) {
          const count = tokenBuffer[i];
          total += count;
          if (count <= 0 || total >= pixels) {
            throw new Error("invalid RLE count total");
          }
          palletIndex = readNextIndex(reader, palletMode, initialIndex, runIndex, previousIndex);
          previousIndex = palletIndex;
          runIndex++;
          if (consumer(count, palletIndex) === false) {
            return false;
          }
        }
      }
    } else {
      while (runIndex < explicitCount) {
        const tokenCount = codec.readToken(reader, tokenBuffer, explicitCount - runIndex);
        for (let i = 0; i < tokenCount; i++) {
          const count = tokenBuffer[i];
          total += count;
          if (count <= 0 || total >= pixels) {
            throw new Error("invalid RLE count total");
          }
          const palletIndex = readNextIndex(reader, palletMode, initialIndex, runIndex, previousIndex);
          previousIndex = palletIndex;
          runIndex++;
          if (consumer(count, palletIndex) === false) {
            return false;
          }
        }
      }
    }
    const last = pixels - total;
    if (last <= 0) {
      throw new Error("RLE count total does not leave final run");
    }
    return consumer(last, readNextIndex(reader, palletMode, initialIndex, runIndex, previousIndex)) !== false;
  }

  throw new Error("invalid RLE data encoding");
}

function readNextIndex(reader, palletMode, initialIndex, runIndex, previousIndex) {
  if (palletMode === RLE_PALLET_2) {
    if (initialIndex === null || initialIndex === undefined) {
      throw new Error("initial index is required");
    }
    return (initialIndex + runIndex) % 2;
  }
  if (palletMode === RLE_PALLET_3 || palletMode === RLE_PALLET_5) {
    if (initialIndex === null || initialIndex === undefined) {
      throw new Error("initial index is required");
    }
    if (runIndex === 0) {
      return initialIndex;
    }
    if (previousIndex === null || previousIndex === undefined) {
      throw new Error("previous index is required");
    }
    const bits = palletMode === RLE_PALLET_3 ? 1 : 2;
    const modulus = palletMode === RLE_PALLET_3 ? 3 : 5;
    return (previousIndex + reader.readBitsAsInt32(bits) + 1) % modulus;
  }
  if (palletMode === RLE_PALLET_16) {
    return reader.readBitsAsInt32(4);
  }
  throw new Error("invalid RLE pallet mode");
}

function shortValueBitsAdd(valueBitsAdd) {
  return valueBitsAdd & 0x03;
}

function shortValueRunBitsAdd(valueBitsAdd) {
  return (valueBitsAdd >> 2) & 0x01;
}

function singleEdgeDValueFormat(valueBitsAdd) {
  return Math.floor(valueBitsAdd / 5);
}

function singleEdgeMbUIntReduceBits(valueBitsAdd) {
  const code = valueBitsAdd % 5;
  return code === 0 ? null : code + 1;
}
