import { BytesReader } from "../../io/BytesReader.js";

const CHUNK_NAME = "GLCH";
const VERSION = "WGSMapSet/3";

export class WGSMapSetHeader3 {
  constructor(reader) {
    if (reader.readAscii(4) !== CHUNK_NAME) {
      throw new Error("invalid WGSMapSet/3 chunk name");
    }
    const size = reader.readMbUInt();
    const payload = new BytesReader(reader.bytes, reader.pos, size);
    reader.skipInByte(size);

    this.version = payload.readBStrAscii(16);
    if (this.version !== VERSION) {
      throw new Error(`invalid WGSMapSet/3 version: ${this.version}`);
    }
    this.unitInvX = payload.readMbUInt();
    this.unitInvY = payload.readMbUInt();
    if (this.unitInvX <= 0 || this.unitInvY <= 0) {
      throw new Error("WGSMapSet/3 unit inverses must be positive");
    }
    const metadataLength = payload.readMbUInt();
    this.metadata = metadataLength === 0 ? null : new TextDecoder().decode(payload.readAsBytes(metadataLength));
    this.numOfMaps = payload.readMbUInt();
    if (this.numOfMaps <= 0) {
      throw new Error("WGSMapSet/3 must contain at least one map");
    }
    this.mapSet = [];
    for (let i = 0; i < this.numOfMaps; i++) {
      this.mapSet.push({ west: payload.readMbInt(), south: payload.readMbInt() });
    }
    if (payload.pos !== payload.end) {
      throw new Error("WGSMapSet/3 header has trailing bytes");
    }
  }

}
