export const RectAnchor = Object.freeze({
  CENTER: "center",
  SOUTHWEST: "southwest",
  NORTHWEST: "northwest",
  NORTHEAST: "northeast",
  SOUTHEAST: "southeast",
});

export class PixelRectSelector {
  constructor(x, y, width, height, options = {}) {
    validateSize(width, height);
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.anchor = options.anchor ?? RectAnchor.SOUTHWEST;
  }

  resolveRect() {
    return resolveRectByAnchor(this.x, this.y, this.width, this.height, this.anchor);
  }

  readRaster(reader) {
    return reader.readWgsRect(this.resolveRect());
  }
}

export class WgsPointRectSelector {
  constructor(lon, lat, width, height, options = {}) {
    validateSize(width, height);
    this.lon = lon;
    this.lat = lat;
    this.width = width;
    this.height = height;
    this.anchor = options.anchor ?? RectAnchor.CENTER;
  }

  resolvePoint(reader) {
    validateLonLat(this.lon, this.lat);
    return {
      x: Math.round(this.lon * reader.unitInvX),
      y: Math.round(this.lat * reader.unitInvY),
    };
  }

  resolveRect(reader) {
    const point = this.resolvePoint(reader);
    return resolveRectByAnchor(point.x, point.y, this.width, this.height, this.anchor);
  }

  readRaster(reader) {
    return reader.readWgsRect(this.resolveRect(reader));
  }
}

function resolveRectByAnchor(x, y, width, height, anchor = RectAnchor.SOUTHWEST) {
  validateSize(width, height);
  switch (anchor) {
    case RectAnchor.SOUTHWEST:
      return { x, y, width, height };
    case RectAnchor.CENTER:
      return {
        x: x - Math.floor(width / 2),
        y: y - Math.floor(height / 2),
        width,
        height,
      };
    case RectAnchor.NORTHWEST:
      return { x, y: y - height, width, height };
    case RectAnchor.NORTHEAST:
      return { x: x - width, y: y - height, width, height };
    case RectAnchor.SOUTHEAST:
      return { x: x - width, y, width, height };
    default:
      throw new Error(`unsupported RectAnchor: ${anchor}`);
  }
}

function validateSize(width, height) {
  if (!Number.isInteger(width) || width <= 0 || !Number.isInteger(height) || height <= 0) {
    throw new RangeError("width and height must be positive integers");
  }
}

function validateLonLat(lon, lat) {
  if (!Number.isFinite(lon) || !Number.isFinite(lat)) {
    throw new TypeError("lon and lat must be finite numbers");
  }
}
